var X={"australia": {"h": "<div class=\"hero\" style=\"padding:44px 0 90px\"><div class=\"w\" style=\"grid-template-columns:1fr\"><div><p style=\"font-size:13px;margin:0 0 14px\"><a href=\"#/home\" style=\"color:var(--navy)\">BlueZone</a> / <a href=\"#/p/destinations\" style=\"color:var(--navy)\">Study destinations</a> / Study in Australia</p><h1 style=\"font-size:44px;max-width:800px\">Study in Australia: visa, costs, universities and work rights for Pakistani students</h1><p>A researched guide with 2026 figures from official and industry sources. Last verified 29 September 2026.</p><a class=\"btn\" href=\"#/contact\">Book free counselling</a></div></div></div><div class=\"w\"><div class=\"facts\"><div class=\"fc\"><b>A$2,500</b><span>Student visa charge, from 1 July 2026</span></div><div class=\"fc\"><b>A$29,710</b><span>Living-cost funds for 12 months, single applicant</span></div><div class=\"fc\"><b>48 hrs</b><span>Work limit per fortnight during study periods</span></div><div class=\"fc\"><b>Feb + Jul</b><span>Main intakes, with some later starts</span></div></div></div><section><div class=\"w\"><h2>Why Pakistani students choose Australia</h2><ul><li>A large choice of universities and vocational providers, with strong subject depth in engineering, IT, business, health and education.</li><li>Global rankings: nine Australian universities are in the QS 2026 top 100, and UNSW ranks first in the country for employment outcomes in that edition.</li><li>Work rights during study help with living costs, and graduates can look at the Temporary Graduate visa.</li><li>Established Pakistani and South Asian communities in Sydney, Melbourne, Brisbane and Perth make settling in easier.</li></ul></div></section><section class=\"alt\"><div class=\"w\"><h2>Student visa (subclass 500): step by step</h2><ol class=\"tlv\"><li data-n=\"1\"><b>Get an offer</b>Apply to a CRICOS-registered course and accept your offer.</li><li data-n=\"2\"><b>Pay the deposit and receive your CoE</b>You cannot lodge the visa without an electronic Confirmation of Enrolment.</li><li data-n=\"3\"><b>Buy OSHC</b>Overseas Student Health Cover must cover your whole stay.</li><li data-n=\"4\"><b>Prepare your Genuine Student answers</b>Explain your study, financial and career reasoning clearly and specifically.</li><li data-n=\"5\"><b>Gather funds and English evidence</b>Tests generally need to be taken in person. Show genuine access to the required funds.</li><li data-n=\"6\"><b>Lodge in ImmiAccount</b>Pay the visa charge, complete health and biometrics if asked, and reply quickly to any request.</li></ol><div class=\"note\" style=\"margin-top:26px\">Common refusal reasons: not enough proof of funds, a weak Genuine Student response, English requirements not met, incomplete or inconsistent documents, and health or character issues.</div></div></section><section><div class=\"w\"><h2>What it costs (2026)</h2><div class=\"tw\"><table><thead><tr><th>Item</th><th>Amount</th><th>Notes</th></tr></thead><tbody><tr><td>Subclass 500 visa charge</td><td>A$2,500</td><td>Up from A$2,000. Non-refundable. Applies to applications lodged from 1 July 2026.</td></tr><tr><td>Living-cost funds to show</td><td>A$29,710 per year</td><td>Single applicant. Extra amounts apply for a partner or children.</td></tr><tr><td>OSHC</td><td>Roughly A$500 to A$700 per year for a single student</td><td>Varies by insurer and length of cover.</td></tr><tr><td>Tuition</td><td>Set by each university and course</td><td>We give a course-specific quote at counselling.</td></tr><tr><td>Temporary Graduate visa (485)</td><td>A$5,750</td><td>From 1 July 2026, for the main Post-Higher Education Work stream.</td></tr></tbody></table></div><p class=\"src\" style=\"margin-top:12px\">Some websites still show older fees such as A$1,600 or A$2,000. Always confirm on the Home Affairs visa pricing page before you pay.</p></div></section><section class=\"alt\"><div class=\"w\"><h2>Top Australian universities (QS World Rankings 2026 edition)</h2><div class=\"tw\"><table><thead><tr><th>University</th><th>Global rank</th><th>Known for</th></tr></thead><tbody><tr><td>University of Melbourne</td><td>19</td><td>Top-ranked in Australia, strong research</td></tr><tr><td>UNSW Sydney</td><td>20</td><td>Engineering, IT and graduate employment</td></tr><tr><td>University of Sydney</td><td>25</td><td>Medicine, law and broad research</td></tr><tr><td>Australian National University</td><td>32</td><td>Research, policy and sciences</td></tr><tr><td>Monash University</td><td>36</td><td>Large, international, wide course range</td></tr><tr><td>University of Queensland</td><td>42</td><td>Teaching awards and research</td></tr></tbody></table></div><p class=\"src\" style=\"margin-top:12px\">A newer QS 2027 edition has been published. Check topuniversities.com for the latest position, and compare subject rankings for your course.</p></div></section><section><div class=\"w\"><h2>English, work rights and the national cap</h2><ul><li><b>English:</b> the visa minimum is often quoted at IELTS 5.5 overall, but universities usually ask for more, commonly 6.0 to 6.5 or higher for degrees. Your offer letter states the exact score.</li><li><b>Work:</b> up to 48 hours per fortnight during study periods, with no fixed limit in scheduled breaks.</li><li><b>Cap:</b> the government limits new international enrolments through a national planning level. For 2026 it is reported at 295,000 places, shared among providers. Early applications matter.</li></ul></div></section><section class=\"alt\"><div class=\"w\"><h2>After graduation: Temporary Graduate visa (485)</h2><ul><li>The Post-Higher Education Work stream is for graduates of eligible degrees from CRICOS-registered courses.</li><li>Study must be completed on a student visa, taught in English, and total at least 92 weeks over 16 or more months.</li><li>You must lodge within the allowed time after finishing, and meet the English test score for the stream.</li><li>Reported length for degree holders is two to three years. Confirm your exact stream and duration on the Home Affairs page.</li></ul></div></section><section><div class=\"w\"><h2>Frequently asked questions</h2><div class=\"stp\" style=\"max-width:860px\"><details><summary>How much does an Australian student visa cost?</summary><p>The base charge for most Subclass 500 applicants is A$2,500 for applications lodged from 1 July 2026. It is non-refundable. Budget separately for OSHC, health checks and any English test.</p></details><details><summary>How much money must I show for a student visa?</summary><p>A single applicant must show access to A$29,710 for 12 months of living costs, on top of tuition and travel. Home Affairs reviews this figure, so confirm it before you lodge.</p></details><details><summary>Can I work while studying in Australia?</summary><p>Student visa holders can generally work up to 48 hours per fortnight while their course is in session, and without a fixed limit during scheduled course breaks. Check your visa conditions in VEVO.</p></details><details><summary>What is the Genuine Student requirement?</summary><p>Since 23 March 2024 it replaces the old Genuine Temporary Entrant test. You answer targeted online questions about why this course, this provider and this country. Generic answers are a common cause of refusal.</p></details><details><summary>Can I stay and work after I graduate?</summary><p>Many graduates apply for the Temporary Graduate visa (subclass 485). The base charge is A$5,750 from 1 July 2026, and you must meet study, English and timing rules. The length depends on your stream and qualification.</p></details><details><summary>When should I start applying?</summary><p>Start 9 to 12 months before your intake. Main intakes are around February and July, and some providers offer others. Early applications leave time for tests, offers, funds evidence and the visa.</p></details></div></div></section><section class=\"alt\"><div class=\"w\"><h2>Sources and how we verify</h2><p class=\"src\">Figures checked on 29 September 2026 against these pages. This guide is general information, not legal or migration advice. Rules and fees change, so confirm with the Department of Home Affairs before you apply.</p><ul class=\"src\"><li><a href=\"https://www.studyaustralia.gov.au/en/plan-your-move/your-guide-to-visas/student-visa-subclass-500\" target=\"_blank\" rel=\"noopener\">Study Australia: Student visa (subclass 500)</a></li><li><a href=\"https://www.studyaustralia.gov.au/en/plan-your-move/your-guide-to-visas/temporary-graduate-visa-subclass-485\" target=\"_blank\" rel=\"noopener\">Study Australia: Temporary Graduate visa (485)</a></li><li><a href=\"https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/temporary-graduate-485/post-higher-education-work\" target=\"_blank\" rel=\"noopener\">Home Affairs: Post-Higher Education Work stream</a></li><li><a href=\"https://www.topuniversities.com/university-rankings-articles/world-university-rankings/top-universities-australia\" target=\"_blank\" rel=\"noopener\">QS TopUniversities: Top universities in Australia</a></li><li><a href=\"https://www.aeccglobal.com/study-in-australia/visas/student\" target=\"_blank\" rel=\"noopener\">AECC: Student visa guide (financial and cap details)</a></li></ul></div></section><section><div class=\"w\"><div class=\"banner\"><div><h3>Get a plan for your own profile</h3><p>Our Australia office and Pakistan counsellors can check your grades, funds and documents before you apply.</p></div><a class=\"btn\" href=\"#/contact\">Book free counselling</a></div></div></section>", "t": "Study in Australia for Pakistani Students", "f": [["How much does an Australian student visa cost?", "The base charge for most Subclass 500 applicants is A$2,500 for applications lodged from 1 July 2026. It is non-refundable. Budget separately for OSHC, health checks and any English test."], ["How much money must I show for a student visa?", "A single applicant must show access to A$29,710 for 12 months of living costs, on top of tuition and travel. Home Affairs reviews this figure, so confirm it before you lodge."], ["Can I work while studying in Australia?", "Student visa holders can generally work up to 48 hours per fortnight while their course is in session, and without a fixed limit during scheduled course breaks. Check your visa conditions in VEVO."], ["What is the Genuine Student requirement?", "Since 23 March 2024 it replaces the old Genuine Temporary Entrant test. You answer targeted online questions about why this course, this provider and this country. Generic answers are a common cause of refusal."], ["Can I stay and work after I graduate?", "Many graduates apply for the Temporary Graduate visa (subclass 485). The base charge is A$5,750 from 1 July 2026, and you must meet study, English and timing rules. The length depends on your stream and qualification."], ["When should I start applying?", "Start 9 to 12 months before your intake. Main intakes are around February and July, and some providers offer others. Early applications leave time for tests, offers, funds evidence and the visa."]]}};

var C={"uk": {"n": "the UK", "t": "Study in the UK for Pakistani Students", "h": "Study in the UK: visa, costs, universities and Graduate Route for Pakistani students", "facts": [["£558", "Student visa fee, from 8 April 2026"], ["£776", "Health surcharge (IHS) per year of visa"], ["£1,171–£1,529", "Monthly maintenance funds (outside / inside London)"], ["18 months", "Graduate Route length, for those applying from 1 Jan 2027"]], "why": ["Globally recognised universities, with one-year master’s degrees that cut total cost and time.", "Strong industry links, placements and internships built into many courses.", "Graduate Route lets eligible graduates work or look for work after study, with no job offer needed.", "Large Pakistani community in London, Manchester, Birmingham, Glasgow and Leeds."], "steps": [["Get an offer", "Apply through the university or UCAS and receive an unconditional offer."], ["Pay deposit and get your CAS", "A Confirmation of Acceptance for Studies is needed before you can apply."], ["Prove your funds", "Course fee balance plus living costs, held for 28 days in a row."], ["Book TB test and biometrics", "Pakistan is on the UK TB-test list, so an approved clinic test is needed for stays over six months."], ["Apply online and pay IHS", "Pay the visa fee and health surcharge, then submit documents and biometrics."]], "note": "Common refusal reasons: funds not held for the full 28 days, unexplained study gaps, weak reasons for choosing the course, and documents that do not match. Some subjects also need an ATAS certificate.", "cost": [["Student visa fee", "£558", "Same fee inside or outside the UK since 8 April 2026."], ["Immigration Health Surcharge", "£776 per year", "Charged for the full visa length. A 3-year visa is £2,328."], ["Maintenance funds", "£1,171 per month outside London, £1,529 inside London", "For up to 9 months, on top of unpaid tuition on your CAS."], ["Graduate visa", "£937 plus IHS", "Applied from inside the UK after you finish."], ["Tuition", "Set by each university", "We give a course-specific quote at counselling."]], "uni": [["Imperial College London", "Engineering, science and business"], ["University of Oxford", "Research and humanities to sciences"], ["University of Cambridge", "Sciences, engineering and mathematics"], ["UCL", "Wide range, strong in London industry links"], ["University of Edinburgh", "Research, computing and medicine"], ["University of Manchester", "Engineering, business and large student community"], ["King’s College London", "Health, law and social sciences"], ["LSE", "Economics, finance and social sciences"]], "work": ["Degree-level students can usually work up to 20 hours per week in term time. Check your visa vignette.", "Graduate Route: currently 2 years for bachelor’s and master’s, shortening to 18 months from 1 January 2027. Confirm where your dates fall.", "Skilled Worker route is the next step for many graduates and needs a sponsoring employer.", "English: most degrees ask for IELTS 6.0 to 7.0. Some visa routes need a UKVI-approved test, so check your CAS conditions."], "schol": ["Chevening scholarships (fully funded, one-year master’s).", "Commonwealth Scholarships for eligible countries.", "University awards, often 10 to 50 percent of tuition.", "Deadlines are often 6 to 12 months before the intake, so apply early."], "faq": [["How much does a UK student visa cost?", "The visa fee is £558 from 8 April 2026. You also pay the Immigration Health Surcharge of £776 for each year of visa length, at the time of applying."], ["How much money must I show?", "Unpaid tuition plus £1,529 per month in London or £1,171 per month elsewhere, for up to 9 months. Funds must normally stay in the account for 28 consecutive days."], ["Can I work while studying?", "Usually up to 20 hours per week in term time at degree level, and full time in official holidays. Your visa states the exact limit."], ["What is the Graduate Route?", "A post-study visa for eligible graduates of UK degrees. It is 2 years now and is due to be 18 months for applications from 1 January 2027. Fee £937 plus IHS."], ["Do Pakistani students need a TB test?", "Yes. Applicants from Pakistan planning to stay over six months need a TB test from an approved clinic, and the certificate goes with the visa application."], ["When should I apply?", "Start 8 to 10 months before the September intake. January intake is available on many courses, and CAS can be issued up to 6 months before the course starts."]], "src": [["GOV.UK: Student visa", "https://www.gov.uk/student-visa"], ["GOV.UK: Graduate visa", "https://www.gov.uk/graduate-visa"], ["UKCISA: fees and funds guidance", "https://www.ukcisa.org.uk"], ["QS World University Rankings", "https://www.topuniversities.com/world-university-rankings"]]}, "canada": {"n": "Canada", "t": "Study in Canada for Pakistani Students", "h": "Study in Canada: study permit, costs, universities and PGWP for Pakistani students", "facts": [["C$150", "Study permit fee (biometrics C$85)"], ["C$23,448", "Living funds, single applicant, from 1 Sep 2026"], ["408,000", "Study permits IRCC expects to issue in 2026"], ["Sep / Jan / May", "Main intakes"]], "why": ["Respected universities and colleges, with co-op and paid work terms in many programmes.", "Safe, multicultural cities and a large Pakistani community, especially in Toronto and Vancouver.", "Off-campus work rights during study and a possible Post-Graduation Work Permit.", "Master’s and PhD applicants at public institutions skip the PAL from 1 January 2026."], "steps": [["Choose a DLI and programme", "Only Designated Learning Institutions can host international students."], ["Get your letter of acceptance", "Accept the offer and pay any deposit the school asks for."], ["Get a PAL if required", "Most undergraduate and college applicants need a Provincial Attestation Letter. Master’s and PhD at public DLIs do not."], ["Prepare funds and documents", "Tuition, living funds, travel, police certificate and medical exam if asked."], ["Apply online and give biometrics", "Pay the permit and biometrics fees in the IRCC portal."]], "note": "Common refusal reasons: unclear study plan, low or unexplained funds, a programme that does not fit your past studies, and weak ties to leave at the end of study. Student Direct Stream is closed, so all Pakistani applicants use the regular stream.", "cost": [["Study permit fee", "C$150", "Non-refundable."], ["Biometrics", "C$85", "Paid once, valid for a set period."], ["Living funds to show", "C$23,448", "Single applicant outside Quebec, for applications from 1 September 2026. Was C$22,895."], ["Tuition", "Set by each institution", "Must be covered on top of living funds. Add return travel."], ["GIC", "Optional", "Accepted as proof of funds, no longer compulsory."]], "uni": [["University of Toronto", "Broad research, medicine, engineering"], ["McGill University", "Research, medicine, Montreal (French context)"], ["University of British Columbia", "Sciences, forestry, business"], ["University of Waterloo", "Co-op, engineering and computer science"], ["McMaster University", "Health sciences and engineering"], ["University of Alberta", "Energy, engineering and research"]], "work": ["Eligible students can work off campus, currently up to 24 hours per week in term time. Confirm on IRCC before you rely on it.", "PGWP: up to 3 years, depending on programme length. Language and field-of-study rules apply, so check before choosing a diploma.", "Express Entry and provincial nominee programmes are the usual PR routes, and rules shift often.", "English: IELTS Academic 6.0 to 6.5 for many degrees, higher for graduate study."], "schol": ["University entrance awards from many DLIs.", "Lester B. Pearson scholarship at the University of Toronto.", "Vanier and other doctoral funding through Canadian institutions.", "Research assistantships for funded master’s and PhD places."], "faq": [["How much money must I show for a Canada study permit?", "From 1 September 2026, a single applicant outside Quebec must show at least C$23,448 for living costs, plus first-year tuition and return travel."], ["Do I need a PAL?", "Most undergraduate, diploma and certificate applicants do. Master’s and PhD students at public DLIs have not needed one since 1 January 2026."], ["How many hours can I work?", "Eligible students can work off campus, currently up to 24 hours per week in term time and full time in scheduled breaks. Check the current IRCC rule."], ["Is the Student Direct Stream still open?", "No. It is closed, so applicants use the regular stream and provide bank statements, a loan letter or a GIC as proof of funds."], ["What is the PGWP?", "A Post-Graduation Work Permit for graduates of eligible programmes at eligible DLIs. Its length depends on the programme, and some fields need to be on the eligible list."], ["When should I apply?", "Start 8 to 12 months ahead. PAL allocations are limited, so early offers matter."]], "src": [["IRCC: Study permit", "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit.html"], ["IRCC: Proof of financial support", "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html"], ["University of Toronto: Study permit guide", "https://internationalexperience.utoronto.ca/international-student-services/immigration/studying-in-canada/apply-for-your-study-permit"], ["Immigration.ca: 2026 funds update", "https://immigration.ca/canada-increases-study-permit-financial-requirements-what-applicants-must-now-prove/"]]}, "usa": {"n": "the USA", "t": "Study in the USA for Pakistani Students", "h": "Study in the USA: F-1 visa, costs, universities and OPT for Pakistani students", "facts": [["$350", "SEVIS I-901 fee"], ["$185", "F-1 visa application fee"], ["$250", "Visa Integrity Fee, being charged at some posts"], ["12 + 24 mo", "OPT, plus STEM OPT extension"]], "why": ["The widest choice of colleges and universities, from state schools to the Ivy League.", "Flexible degrees, strong research and funded master’s and PhD places with assistantships.", "OPT lets graduates work in their field, and STEM degrees can add 24 months.", "Large Pakistani student and professional networks in Texas, New York, California and Illinois."], "steps": [["Apply and get admitted", "Apply through each university or the Common App, with tests if required."], ["Receive your I-20", "Submit proof of funds to the school and receive the Form I-20."], ["Pay the SEVIS fee", "Pay $350 at fmjfee.com before the interview."], ["Complete DS-160 and book the interview", "Pay the $185 fee and follow the current Embassy instructions."], ["Attend the visa interview", "Show your I-20, funds, study plan and ties to Pakistan."]], "note": "Important 2026 change: DHS published a final rule on 17 July 2026 ending open-ended Duration of Status for F-1 students. From 15 September 2026, admission is for a fixed period, generally up to four years, with a shorter departure window. The rule faces legal challenges, so confirm with your school’s DSO.", "cost": [["SEVIS I-901 fee", "$350", "Paid once per SEVIS record. Not refundable."], ["F-1 visa application fee", "$185", "Paid before the interview."], ["Visa Integrity Fee", "$250", "Introduced under a 2025 law and reported at some posts. Confirm at the time you apply."], ["OPT work permit (I-765)", "About $470 online", "Paid when you file for OPT. Premium processing costs extra."], ["Tuition and living costs", "Set by each school", "The I-20 lists the estimated total you must show funds for."]], "uni": [["MIT", "Engineering, computing and research"], ["Stanford University", "Technology, business and research"], ["Harvard University", "Broad research, law, medicine, business"], ["Caltech", "Sciences and engineering, small and research-heavy"], ["UC Berkeley", "Public research, engineering and computing"], ["Carnegie Mellon", "Computer science, AI and robotics"], ["Georgia Tech", "Engineering and computing at public-school cost"], ["State universities", "Good value for many engineering and business courses"]], "work": ["On-campus work is usually limited to 20 hours per week in term time.", "CPT allows paid work linked to your course after the first academic year in most programmes.", "OPT: 12 months after graduation. STEM OPT adds 24 months for eligible degrees and E-Verify employers.", "H-1B and other work visas are separate and competitive. Rules change often, so plan with a school advisor."], "schol": ["University merit awards, especially at private schools.", "Research and teaching assistantships for many master’s and PhD places.", "Fulbright programme for Pakistani graduate students.", "Test rules: SAT or ACT are optional at many schools. GRE or GMAT depend on programme."], "faq": [["How much does an F-1 visa cost?", "Most students pay the $350 SEVIS fee and the $185 visa application fee. A $250 Visa Integrity Fee is also being collected at some posts, so check current instructions."], ["What is the new fixed admission rule?", "From 15 September 2026, F-1 students are admitted for a fixed period tied to their programme, generally capped at four years. Extensions go through USCIS, and the post-study departure window shortens to 30 days for new admissions."], ["Can I work in the USA as a student?", "On campus up to 20 hours per week during term. Off-campus work is only through CPT or OPT and needs authorisation."], ["How long is OPT?", "12 months after your degree. STEM graduates at E-Verify employers can apply for another 24 months."], ["Do I need IELTS or TOEFL?", "Most schools ask for one, and many accept Duolingo or similar. Requirements differ by university, so check your programme page."], ["When should I apply?", "Start 10 to 14 months before Fall intake. Interview dates can be limited, so book early."]], "src": [["SEVP: I-901 SEVIS fee FAQ", "https://www.ice.gov/sevis/i901/faq"], ["Study in the States (DHS)", "https://studyinthestates.dhs.gov"], ["US Department of State: Student visas", "https://travel.state.gov/content/travel/en/us-visas/study/student-visa.html"], ["Boston University ISSO: Visa Integrity Fee", "https://www.bu.edu/isso/2026/05/19/visa-integrity-fee/"]]}, "new-zealand": {"n": "New Zealand", "t": "Study in New Zealand for Pakistani Students", "h": "Study in New Zealand: visa, costs, universities and post-study work for Pakistani students", "facts": [["NZ$850", "Fee Paying Student Visa, as reported"], ["NZ$20,000", "Living funds per year of study"], ["NZ$1,670", "Post Study Work Visa fee"], ["Up to 3 yrs", "Post Study Work Visa length"]], "why": ["Eight state universities, all in the world rankings, with smaller classes and hands-on teaching.", "One of the safest countries in the world, with a friendly, outdoor lifestyle.", "Degree-level graduates can apply for an open Post Study Work Visa.", "Lower living pressure than the biggest cities elsewhere, with cities like Dunedin and Hamilton."], "steps": [["Get an offer of place", "Apply to an approved provider and accept the offer."], ["Pay tuition as required", "The provider tells you what must be paid before the visa."], ["Arrange funds and insurance", "NZ$20,000 per year for living, plus approved medical and travel insurance."], ["Get medical and police certificates", "Needed for longer courses. A chest X-ray may also be asked for."], ["Apply online with Immigration NZ", "Create a RealMe login, upload documents and pay the fee."]], "note": "Common refusal reasons: funds that do not clearly belong to you or your sponsor, a course that does not fit your background, and missing medical or police documents.", "cost": [["Fee Paying Student Visa", "About NZ$850", "Sources differ, so check the INZ fee page on the day you apply."], ["Living funds to show", "NZ$20,000 per year", "Or NZ$1,667 per month for courses under a year."], ["Tuition", "Set by each institution", "Must be paid or shown as required by your offer."], ["Medical and travel insurance", "Varies", "Approved cover is required for your whole stay."], ["Post Study Work Visa", "NZ$1,670", "Plus you show NZ$5,000 in funds when you apply."]], "uni": [["University of Auckland", "Top-ranked in NZ, wide range, engineering and business"], ["University of Otago", "Health sciences, medicine, dentistry"], ["Victoria University of Wellington", "Law, policy, arts and design"], ["University of Canterbury", "Engineering, science and forestry"], ["Massey University", "Agriculture, veterinary science, aviation"], ["University of Waikato", "Management, computing and law"], ["Lincoln University", "Agriculture and land-based sciences"], ["AUT", "Business, technology and communication"]], "work": ["Many degree students can work up to 20 hours per week in term time, and 25 hours has been reported for 2026. Your visa label shows your exact limit.", "Full-time work is allowed in scheduled holidays for most visas.", "Post Study Work Visa: up to 3 years for degree-level graduates, and shorter for lower levels.", "English: IELTS 6.0 to 6.5 for most degrees."], "schol": ["Manaaki New Zealand Scholarships (government-funded, check the eligible-country list).", "University and faculty scholarships, often for postgraduate research.", "PhD stipends at NZ universities.", "Fees and deadlines change, so confirm with each provider."], "faq": [["How much does a NZ student visa cost?", "The Fee Paying Student Visa is reported at NZ$850 for 2026. Some websites still show older fees, so check the Immigration New Zealand fee page before you pay."], ["How much money must I show?", "NZ$20,000 for each year of study for living costs, or NZ$1,667 per month for courses under a year, plus tuition and return travel."], ["Can I work while studying?", "Most degree students have work rights during term and can work full time in holidays. The hours limit is on your visa label, and 25 hours is reported for 2026."], ["What is the Post Study Work Visa?", "An open work visa for graduates who studied at eligible level and length. Degree-level graduates can get up to 3 years. The fee is NZ$1,670."], ["Which are the main intakes?", "February and July. Some courses start at other times."], ["When should I apply?", "Start 6 to 9 months ahead. Processing times vary by season."]], "src": [["Immigration New Zealand", "https://www.immigration.govt.nz"], ["Study in New Zealand", "https://www.studywithnewzealand.govt.nz"], ["AECC: NZ student visa guide", "https://www.aeccglobal.com/study-in-new-zealand/visas/student"], ["AECC: Post Study Work Visa", "https://www.aeccglobal.com/study-in-new-zealand/visas/post-study-work-visa"]]}, "ireland": {"n": "Ireland", "t": "Study in Ireland for Pakistani Students", "h": "Study in Ireland: visa, costs, universities and the Graduate Scheme for Pakistani students", "facts": [["€60", "Single-entry visa fee (€100 multiple)"], ["€10,000", "Living funds for a year"], ["€6,000", "Minimum tuition to show as paid"], ["12–24 mo", "Stamp 1G graduate permission"]], "why": ["English-speaking EU country with global tech, pharma and finance employers.", "Friendly, safe cities and a compact, well-connected education system.", "Stamp 1G lets eligible graduates stay and work after study.", "Direct access to Europe for travel and career."], "steps": [["Get an offer", "Apply to a course on the Interim List of Eligible Programmes."], ["Pay at least €6,000", "Or the full fee if lower. Keep the receipt for the visa file."], ["Arrange funds and insurance", "€10,000 in accessible funds, and private medical insurance at the required level."], ["Apply via AVATS", "Pay the visa fee, submit the summary form, documents and biometrics."], ["Register in Ireland", "After arrival, register for your Stamp 2 and pay the IRP fee."]], "note": "Common refusal reasons: unexplained study gaps, funds that are not clearly available, an unclear reason for the course, and documents that do not match. Show a clear career link between your past study and the new course.", "cost": [["Visa fee", "€60 single, €100 multiple", "Non-refundable."], ["Living funds", "€10,000", "Courses over 8 months. Shorter courses need €833 per month."], ["Tuition paid", "At least €6,000", "Or the full fee if it is lower."], ["IRP registration", "€300", "Paid in Ireland to receive Stamp 2."], ["Medical insurance", "Varies", "Private cover is required for your stay."]], "uni": [["Trinity College Dublin", "Ireland’s oldest and highest-ranked, wide range"], ["University College Dublin", "Business, science, engineering and medicine"], ["University of Galway", "Medical technology, marine and humanities"], ["University College Cork", "Food science, pharma and health"], ["Dublin City University", "Computing, business and communication"], ["University of Limerick", "Engineering, co-op and technology"]], "work": ["Stamp 2 allows 20 hours per week in term time, and 40 hours in June to September and 15 December to 15 January.", "Stamp 1G: up to 12 months after a bachelor’s, and up to 24 months after a master’s or PhD.", "Critical Skills and General Employment Permits are the next work routes for many graduates.", "English: IELTS 6.0 to 6.5 for most degrees, 6.5 or higher for some postgraduate courses."], "schol": ["Government of Ireland International Education Scholarships.", "University merit awards, often partial tuition.", "Research funding for PhD places through Irish institutions.", "Check eligibility and closing dates on each university page."], "faq": [["How much does an Ireland student visa cost?", "The fee is €60 for a single-entry visa and €100 for multiple entry. After arrival you also pay €300 for IRP registration."], ["How much money must I show?", "€10,000 in accessible funds for the first year if the course is over 8 months, plus proof that at least €6,000 of tuition has been paid."], ["Can I work?", "Up to 20 hours per week in term time and up to 40 hours in the holiday periods on Stamp 2."], ["What is Stamp 1G?", "The Third Level Graduate Programme. It allows graduates from NFQ level 8 to 10 courses to stay for 12 months (bachelor’s) or up to 24 months (master’s and PhD)."], ["Is health insurance required?", "Yes. Private medical insurance is required for the duration of study."], ["When should I apply?", "Start 6 to 8 months before September or January. Visa processing can take several weeks."]], "src": [["Citizens Information: Student visas", "https://www.citizensinformation.ie/en/moving-country/visas-for-ireland/student-visas/"], ["Irish Immigration: Study in Ireland", "https://www.irishimmigration.ie/coming-to-study-in-ireland/"], ["ApplyBoard: Ireland visa guide 2026/27", "https://assist.applyboard.com/hc/en-us/articles/6477955002637-Ireland-Student-Visa-Guide-2026-27-Requirements-Fees-and-Application-Steps"], ["Education in Ireland", "https://www.educationinireland.com"]]}, "malaysia": {"n": "Malaysia", "t": "Study in Malaysia for Pakistani Students", "h": "Study in Malaysia: Student Pass, costs, universities and twinning for Pakistani students", "facts": [["RM 60", "Student Pass fee per year"], ["RM 1,000+", "EMGS processing fee, varies by course"], ["4–8 weeks", "Typical eVAL processing time"], ["12 months", "Minimum health insurance cover"]], "why": ["Globally recognised degrees at a much lower cost than the UK, USA or Australia.", "English-taught programmes, and branch campuses of Monash, Nottingham, Heriot-Watt and others.", "Twinning routes such as 2+1 and 3+0 let you finish a foreign degree with less time abroad.", "Muslim-friendly, low-cost cities such as Kuala Lumpur, with halal food and prayer facilities widely available."], "steps": [["Choose a university and course", "Public universities and private colleges both host international students."], ["Accept the offer and pay the fee", "The university applies to EMGS for you."], ["Receive your eVAL", "The electronic Visa Approval Letter must arrive before you travel."], ["Travel, medical and Student Pass", "Arrive with the eVAL and any Single Entry Visa, then complete the medical screening."], ["Get your pass endorsed", "The Student Pass and i-Kad are issued after arrival."]], "note": "Common delays: missing documents, unclear passport copies, late payment of EMGS fees and incomplete medical screening. Always apply through the university, since EMGS does not accept individual applications.", "cost": [["EMGS processing fee", "About RM 1,000", "Varies by institution and course length. Use the official EMGS fee calculator."], ["Student Pass", "RM 60 per year", "Paid to Malaysian Immigration."], ["Medical screening", "About RM 250", "At an EMGS-approved clinic on arrival."], ["Health insurance", "About RM 500–800 per year", "Bundled through EMGS or your university."], ["Total first-year visa costs", "About RM 1,500 to RM 3,500", "Sources vary widely, so confirm the exact total with your university."]], "uni": [["Universiti Malaya", "Top public university, wide range"], ["Universiti Putra Malaysia", "Agriculture, engineering and life sciences"], ["Universiti Sains Malaysia", "Science, health and research"], ["Universiti Teknologi Malaysia", "Engineering and technology"], ["Monash University Malaysia", "Australian degree on a Malaysian campus"], ["University of Nottingham Malaysia", "UK degree on a Malaysian campus"], ["Heriot-Watt University Malaysia", "Engineering and business, UK degree"], ["Sunway and Taylor’s", "Popular private universities with pathway programmes"]], "work": ["Work rights are very limited. Language-centre students cannot work at all, and other students need permission and may only work in certain sectors during breaks.", "Do not plan to fund your studies through part-time work in Malaysia.", "There is no automatic post-study work visa like the UK or Australia. Graduates usually need an employer to sponsor a work pass.", "English: many courses accept IELTS 5.5 to 6.0, and some accept MUET or English-medium proof. Confirm with the university."], "schol": ["University merit scholarships, often 10 to 50 percent of tuition.", "Malaysian International Scholarship for eligible postgraduate applicants.", "Research assistantships at public universities.", "Confirm dates and eligibility with each institution."], "faq": [["How much does a Malaysia student visa cost?", "The Student Pass itself is RM 60 per year, but the EMGS processing fee, eVAL, medical screening, insurance and i-Kad add up to roughly RM 1,500 to RM 3,500 in the first year, depending on your institution."], ["Do Pakistani students need a visa?", "Yes. The university applies for your Student Pass through EMGS, and you may also need a Single Entry Visa before travel."], ["Can I work in Malaysia while studying?", "Only in limited cases with permission, and language-centre students cannot work at all. Plan your budget without work income."], ["What is twinning?", "A programme where you spend part of the degree in Malaysia and the rest at a partner university abroad, for example 2+1, or take the full foreign degree on a branch campus."], ["How long does it take?", "Typically 4 to 8 weeks for the eVAL. Apply as soon as you accept your offer."], ["When are the intakes?", "Most universities offer January or February, May and September. Some have rolling intakes."]], "src": [["EMGS: Education Malaysia", "https://educationmalaysia.gov.my"], ["Malaysian Immigration Department", "https://www.imi.gov.my"], ["study-abroad.org: Malaysia Student Pass guide", "https://www.study-abroad.org/blog/my-student-visa-guide/"], ["Times Consultant: Malaysia visa from Pakistan", "https://timesconsultant.com/blog/how-to-apply-for-a-malaysia-study-visa-from-pakistan/"]]}};
